package com.acxiom.crm.api; import com.acxiom.crm.lead.*; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.List;
@RestController @RequestMapping("/api/leads") public class LeadApiController {private final LeadRepository repo; public LeadApiController(LeadRepository r){repo=r;} @GetMapping public List<Lead> all(){return repo.findAll();} @GetMapping("/{id}") public Lead one(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));} @PostMapping @ResponseStatus(HttpStatus.CREATED) public Lead create(@Valid @RequestBody Lead l){return repo.save(l);} @PutMapping("/{id}") public Lead update(@PathVariable Long id,@Valid @RequestBody Lead l){Lead o=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));o.setName(l.getName());o.setEmail(l.getEmail());o.setPhone(l.getPhone());o.setCompany(l.getCompany());o.setSource(l.getSource());o.setStatus(l.getStatus());o.setExpectedValue(l.getExpectedValue());o.setAssignedTo(l.getAssignedTo());return repo.save(o);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){repo.deleteById(id);} }
